#!/usr/bin/env python3
"""enzyme/conservation-msa-analyzer — auto-generated run.py (archetype=msa_conservation).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "msa_conservation"
BRAIN = "enzyme"
SKILL = "conservation-msa-analyzer"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'conservation-msa-analyzer', 'msa_path': '', 'n_sequences': 0, 'conservation_csv': '', 'diagnostics': {'brain': 'enzyme', 'archetype': 'msa_conservation'}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """MSA conservation 计算:用户提供 MSA(FASTA),用 BioPython 算 Shannon entropy per column。
    (host 无 mafft,要求用户给已对齐的 MSA。)
    """
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401
    msa = payload.get("msa_fasta") or payload.get("msa_path")
    out_dir = payload.get("out_dir") or _tempfile.mkdtemp(prefix="cons_")
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "tool": "Biopython.AlignIO + scipy.entropy", "out_dir": out_dir,
                   "note": "host 无 mafft;用户需提供已对齐 MSA"}
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "msa_path": "", "n_sequences": 0,
                "conservation_csv": "", "diagnostics": {**diagnostics, "dry": True}}
    if not msa or not _os.path.isfile(msa):
        return {"ok": False, "error": "需要 msa_fasta (已对齐 FASTA)", "diagnostics": diagnostics}
    out_csv = _os.path.join(out_dir, "conservation.csv")
    script = (
        "import json, sys, os, csv, math\n"
        "from Bio import AlignIO\n"
        "from collections import Counter\n"
        f"msa_path = {msa!r}; out_csv = {out_csv!r}\n"
        "os.makedirs(os.path.dirname(out_csv), exist_ok=True)\n"
        "aln = AlignIO.read(msa_path, 'fasta')\n"
        "n_cols = aln.get_alignment_length(); n_seq = len(aln)\n"
        "results = []\n"
        "for i in range(n_cols):\n"
        "    col = [rec.seq[i].upper() for rec in aln]\n"
        "    cnts = Counter(c for c in col if c not in ('-','.'))\n"
        "    total = sum(cnts.values()) or 1\n"
        "    H = -sum((c/total)*math.log2(c/total) for c in cnts.values() if c)\n"
        "    results.append({'col': i+1, 'shannon_H': round(H, 3),\n"
        "                    'consensus': cnts.most_common(1)[0][0] if cnts else '-',\n"
        "                    'gap_frac': round(col.count('-')/len(col), 3)})\n"
        "with open(out_csv, 'w') as fh:\n"
        "    w = csv.DictWriter(fh, fieldnames=['col','shannon_H','consensus','gap_frac']); w.writeheader()\n"
        "    for r in results: w.writerow(r)\n"
        "json.dump({'conservation_csv': out_csv, 'n_sequences': n_seq, 'n_columns': n_cols}, sys.stdout)\n"
    )
    t0 = _time.time()
    r = run_tool(["python3", "-c", script], timeout=120)
    diagnostics["subprocess"] = {"wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "conservation 算失败"),
                "stderr": r.get("stderr", "")[-300:], "diagnostics": diagnostics}
    try:
        parsed = json.loads(r["stdout"])
    except json.JSONDecodeError as e:
        return {"ok": False, "error": f"stdout 解析失败: {e}", "diagnostics": diagnostics}
    return {"ok": True, "skill_id": SKILL,
            "msa_path": msa, "conservation_csv": parsed.get("conservation_csv", ""),
            "n_sequences": parsed.get("n_sequences", 0),
            "runtime_sec": round(_time.time() - t0, 2),
            "diagnostics": {**diagnostics, **parsed}}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
